                        o_ready <= 0;
                        o_overflow <= 0;
                        if (i_enable && i_start) begin
                            state <= LOAD;
                        end
                    end

                    LOAD: begin
                        if (i_enable) begin
                            reg_operand_a <= i_operand_a;
                            reg_operand_b <= i_operand_b;
                            state <= COMPUTE;
                        end else begin
                            state <= IDLE;
                        end
                    end

                    COMPUTE: begin
                        if (i_enable) begin
                            if (i_mode == 0) begin
                                result = reg_operand_a + reg_operand_b;
                                signed_overflow = 
                                    (~reg_operand_a[DATA_WIDTH-1] & ~reg_operand_b[DATA_WIDTH-1] & result[DATA_WIDTH-1]) | 
                                    (reg_operand_a[DATA_WIDTH-1] & reg_operand_b[DATA_WIDTH-1] & ~result[DATA_WIDTH-1]);
                            end else begin
                                result = reg_operand_a - reg_operand_b;
                                signed_overflow = 
                                    (~reg_operand_a[DATA_WIDTH-1] & reg_operand_b[DATA_WIDTH-1] & result[DATA_WIDTH-1]) | 
                                    (reg_operand_a[DATA_WIDTH-1] & ~reg_operand_b[DATA_WIDTH-1] & ~result[DATA_WIDTH-1]);
